import { apprv_rej_purchase_orders } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    purchaseUpdate: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    purchaseUpdate: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async status_update() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(apprv_rej_purchase_orders, {
          input: {
            // order_dispatch_comments: "",
            order_delivery_status: "COMPLETED",
            initiate_id: this.rowInfo.initiate_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.apprv_rej_purchase_orders);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
